/**
 * shuffleArray — Fisher-Yates shuffle (in-place copy)
 * Returns a new array with elements in random order.
 * Imperative: explicit for-loop, temp variable, index arithmetic.
 */
function shuffleArray(sourceArray) {
  const arr = sourceArray.slice();          // copy so original bank is untouched
  for (let i = arr.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  return arr;
}

