// ─────────────────────────────────────────────────────────────────────────────
//  SERVICE FUNCTIONS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * getQuestionsWithAnswers
 * Returns the full question array (including correctIndex) for server-side use.
 * Used by ExamService to build the answer key when grading a submission.
 */
function getQuestionsWithAnswers(subjectId, examTypeId) {
  const key = subjectId + '-' + examTypeId;
  return QUESTION_BANK[key] || QUESTION_BANK.default;
}

/**
 * getQuestionsForClient
 * Returns a randomised (Fisher-Yates shuffle) array of questions with
 * correctIndex stripped out so answers never leave the server.
 * Randomisation is applied to all subjects per professor survey preferences.
 */
function getQuestionsForClient(subjectId, examTypeId) {
  const sourceQuestions = getQuestionsWithAnswers(subjectId, examTypeId);
  const shuffled = shuffleArray(sourceQuestions);   // random order every time
  const clientQuestions = [];

  // Build client-safe array — imperative loop, no Array methods
  for (let i = 0; i < shuffled.length; i += 1) {
    const q = shuffled[i];
    clientQuestions.push({
      id: q.id,
      text: q.text,
      choices: q.choices       // choice ORDER is kept; only correctIndex is hidden
    });
  }

  return clientQuestions;
}

function getExamConfig(subjectId, examTypeId) {
  const questions = getQuestionsWithAnswers(subjectId, examTypeId);
  const durations = {
    ccincoml: { quiz: 15, midterms: 75, finals: 75 },
    ccsfen1l: { quiz: 30, midterms: 90, finals: 90 },
    ctprfiss: { quiz: 30, midterms: 120, finals: 120 }
  };
  const normalizedSubject = String(subjectId || "").toLowerCase();
  const normalizedExamType = String(examTypeId || "").toLowerCase();
  return {
    subjectId: normalizedSubject,
    examType: normalizedExamType,
    itemCount: questions.length,
    durationMinutes: durations[normalizedSubject]?.[normalizedExamType] || 30,
    randomize: true
  };
}

module.exports = { getQuestionsForClient, getQuestionsWithAnswers, getExamConfig };
